const uploaded = $json;
const c = $('Validate Captions and Finalize').item.json || {};

/**
 * Current Postiz integration IDs.
 * Reconnect korle ID change hote pare.
 */
const FACEBOOK_ID = 'YOUR_FACEBOOK_INTEGRATION_ID';
const INSTAGRAM_ID = 'YOUR_INSTAGRAM_INTEGRATION_ID';
const TIKTOK_ID = 'YOUR_TIKTOK_INTEGRATION_ID';
const YOUTUBE_ID = 'YOUR_YOUTUBE_INTEGRATION_ID';
const THREADS_ID = 'YOUR_THREADS_INTEGRATION_ID';


const X_ID = 'YOUR_X_INTEGRATION_ID';
const PINTEREST_ID = 'YOUR_PINTEREST_INTEGRATION_ID';

/**
 * Platform switches.
 */
const ENABLE_FACEBOOK = true;
const ENABLE_INSTAGRAM = true;
const ENABLE_TIKTOK = true;
const ENABLE_YOUTUBE = true;
const ENABLE_THREADS = true;

const ENABLE_X = false;
const ENABLE_PINTEREST = false;

/**
 * TikTok sandbox/private test:
 * SELF_ONLY
 *
 * TikTok production approve + reconnect korar por:
 * PUBLIC_TO_EVERYONE
 */
const TIKTOK_PRIVACY_LEVEL = 'SELF_ONLY';

function hasValidId(id) {
  if (!id || typeof id !== 'string') return false;

  const value = id.trim();

  if (!value) return false;
  if (value.includes('PASTE_')) return false;
  if (value.includes('YOUR_')) return false;
  if (value.toLowerCase() === 'blank') return false;

  return true;
}

function cleanText(value, fallback = '') {
  if (value === null || value === undefined) return fallback;

  const cleaned = String(value)
    .replace(/\r/g, '')
    .replace(/\u0000/g, '')
    .trim();

  return cleaned || fallback;
}

function cleanSingleLine(value, fallback = '') {
  return cleanText(value, fallback)
    .replace(/\n+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function limitText(value, max, fallback = '') {
  const text = cleanSingleLine(value, fallback);

  if (text.length <= max) return text;

  const cut = text.slice(0, max + 1);
  const lastSpace = cut.lastIndexOf(' ');

  return (lastSpace > 20 ? cut.slice(0, lastSpace) : text.slice(0, max))
    .replace(/[.,;:|/-]+$/g, '')
    .trim();
}

function makeTikTokTitle(value) {
  return limitText(value, 80, 'New Video');
}

function makeYouTubeTitle(value) {
  return limitText(value, 95, 'New Video');
}

function makeYouTubeDescription(value) {
  const description = cleanText(value);

  if (!description) {
    return 'This video explains the workflow and shows the main automation process clearly.';
  }

  return description.slice(0, 4900).trim();
}

const uploadId =
  uploaded.id ||
  uploaded.uploadId ||
  uploaded.postiz_upload_id ||
  uploaded.data?.id ||
  uploaded.result?.id ||
  '';

const uploadPath =
  uploaded.path ||
  uploaded.uploadPath ||
  uploaded.url ||
  uploaded.data?.path ||
  uploaded.result?.path ||
  '';

if (!uploadId) {
  throw new Error('Postiz upload ID missing. Please check Postiz Upload node response.');
}

const media = [
  {
    id: uploadId,
    path: uploadPath,
  },
];

const posts = [];
const skippedPlatforms = [];

function addPost(platformName, enabled, integrationId, postValue, settings) {
  if (!enabled) {
    skippedPlatforms.push(`${platformName}: disabled`);
    return;
  }

  if (!hasValidId(integrationId)) {
    skippedPlatforms.push(`${platformName}: missing integration ID`);
    return;
  }

  posts.push({
    integration: {
      id: integrationId,
    },
    value: [
      {
        content: cleanText(postValue),
        image: media,
      },
    ],
    settings,
  });
}

/**
 * Facebook
 */
addPost(
  'facebook',
  ENABLE_FACEBOOK,
  FACEBOOK_ID,
  c.facebookMessage || c.instagramCaption || c.youtubeDescription || '',
  {
    __type: 'facebook',
  }
);

/**
 * Instagram
 */
addPost(
  'instagram',
  ENABLE_INSTAGRAM,
  INSTAGRAM_ID,
  c.instagramCaption || c.facebookMessage || c.youtubeDescription || '',
  {
    __type: 'instagram',
    post_type: 'post',
    is_trial_reel: false,
    collaborators: [],
  }
);

/**
 * TikTok
 */
addPost(
  'tiktok',
  ENABLE_TIKTOK,
  TIKTOK_ID,
  c.tiktokCaption || c.instagramCaption || c.youtubeTitle || '',
  {
    __type: 'tiktok',
    title: makeTikTokTitle(c.tiktokCaption || c.youtubeTitle || 'New Video'),
    privacy_level: TIKTOK_PRIVACY_LEVEL,
    duet: false,
    stitch: false,
    comment: true,
    autoAddMusic: 'no',
    brand_content_toggle: false,
    brand_organic_toggle: false,
    video_made_with_ai: false,
    content_posting_method: 'DIRECT_POST',
  }
);

/**
 * YouTube - fixed clean payload
 * Tags empty rakha holo, karon eta diye YouTube posting fixed hoyeche.
 */
addPost(
  'youtube',
  ENABLE_YOUTUBE,
  YOUTUBE_ID,
  makeYouTubeDescription(
    c.youtubeDescription ||
    c.instagramCaption ||
    c.facebookMessage ||
    c.contentBrief?.workflowSummary ||
    ''
  ),
  {
    __type: 'youtube',
    title: makeYouTubeTitle(
      c.youtubeTitle ||
      c.contentBrief?.topic ||
      c.videoName ||
      'New Video'
    ),
    type: 'public',
    selfDeclaredMadeForKids: 'no',
    thumbnail: null,
    tags: [],
  }
);

/**
 * Threads
 */
addPost(
  'threads',
  ENABLE_THREADS,
  THREADS_ID,
  c.threadsCaption || c.instagramCaption || c.facebookMessage || '',
  {
    __type: 'threads',
  }
);

/**
 * X / Twitter
 */
addPost(
  'x',
  ENABLE_X,
  X_ID,
  c.xCaption || c.twitterCaption || c.threadsCaption || c.instagramCaption || '',
  {
    __type: 'x',
  }
);

/**
 * Pinterest
 */
addPost(
  'pinterest',
  ENABLE_PINTEREST,
  PINTEREST_ID,
  c.pinterestDescription || c.instagramCaption || c.youtubeDescription || '',
  {
    __type: 'pinterest',
    title: makeYouTubeTitle(c.pinterestTitle || c.youtubeTitle || 'New Video'),
  }
);

if (!posts.length) {
  throw new Error('No valid Postiz integrations found. Enable at least one platform and add its integration ID.');
}

return {
  json: {
    postizPayload: {
      type: 'now',
      date: new Date().toISOString(),
      shortLink: false,
      tags: [],
      posts,
    },

    videoName: c.videoName || uploaded.name || '',
    videoId: c.videoId || '',
    uploadId,
    uploadPath,
    platformCount: posts.length,
    platforms: posts.map((post) => post.settings.__type),
    skippedPlatforms,
    contentBrief: c.contentBrief || {},

    debug: {
      mode: 'ALL_PLATFORMS_ENABLED',
      youtubeIntegrationId: YOUTUBE_ID,
      tiktokIntegrationId: TIKTOK_ID,
      tiktokPrivacyLevel: TIKTOK_PRIVACY_LEVEL,
      youtubeTagsDisabled: true,
    },
  },
};

const visualRaw = $('Visual Summary Helper').item.json || {};
const whisper = $('Whisper Transcription').item.json || {};
const drive = $('Google Drive Trigger').item.json || {};

const cleanText = (text = '') =>
  String(text || '').replace(/\s+/g, ' ').trim();

const rawTranscript = cleanText(whisper.text || whisper.raw?.text || '');

const segments = whisper.segments || whisper.raw?.segments || [];

const avgLogprobValues = segments
  .map(s => typeof s.avg_logprob === 'number' ? s.avg_logprob : null)
  .filter(v => v !== null);

const noSpeechValues = segments
  .map(s => typeof s.no_speech_prob === 'number' ? s.no_speech_prob : null)
  .filter(v => v !== null);

const temperatureValues = segments
  .map(s => typeof s.temperature === 'number' ? s.temperature : null)
  .filter(v => v !== null);

const avgLogprob = avgLogprobValues.length
  ? avgLogprobValues.reduce((a, b) => a + b, 0) / avgLogprobValues.length
  : null;

const maxNoSpeechProb = noSpeechValues.length
  ? Math.max(...noSpeechValues)
  : null;

const maxTemperature = temperatureValues.length
  ? Math.max(...temperatureValues)
  : null;

const wordCount = rawTranscript.split(/\s+/).filter(Boolean).length;

const transcriptReliable =
  rawTranscript.length > 20 &&
  wordCount >= 5 &&
  (avgLogprob === null || avgLogprob > -1.5) &&
  (maxTemperature === null || maxTemperature < 0.8) &&
  (maxNoSpeechProb === null || maxNoSpeechProb < 0.75);

const visualEvidence = {
  category: visualRaw.category || '',
  topic: visualRaw.topic || '',
  main_subject: visualRaw.main_subject || '',
  visible_action: visualRaw.visible_action || visualRaw.action || '',
  scene: visualRaw.scene || '',
  visual_details: visualRaw.visual_details || '',
  mood: visualRaw.mood || '',
  caption_angle: visualRaw.caption_angle || '',
  creative_hooks: Array.isArray(visualRaw.creative_hooks) ? visualRaw.creative_hooks : [],
  safe_keywords: Array.isArray(visualRaw.safe_keywords) ? visualRaw.safe_keywords : [],
  avoid_claims: Array.isArray(visualRaw.avoid_claims) ? visualRaw.avoid_claims : [],
  confidence: visualRaw.confidence ?? null,
};

const visualEvidenceText = cleanText([
  visualEvidence.category,
  visualEvidence.topic,
  visualEvidence.main_subject,
  visualEvidence.visible_action,
  visualEvidence.scene,
  visualEvidence.visual_details,
  visualEvidence.caption_angle,
  ...(visualEvidence.creative_hooks || []),
  ...(visualEvidence.safe_keywords || []),
].join(' '));

const currentVideoId = cleanText(drive.id || '');
const currentVideoName = cleanText(drive.name || '');

return {
  json: {
    currentVideoId,
    currentVideoName,
    generatedAt: new Date().toISOString(),

    transcript: rawTranscript,
    transcriptReliable,
    transcriptQuality: {
      avgLogprob,
      maxNoSpeechProb,
      maxTemperature,
      wordCount,
    },

    visualRaw,
    visualEvidence,
    visualEvidenceText,

    evidenceText: cleanText([
      `VIDEO FILE: ${currentVideoName}`,
      `VIDEO ID: ${currentVideoId}`,
      `TRANSCRIPT: ${rawTranscript}`,
      `VISUAL EVIDENCE: ${visualEvidenceText}`,
    ].join('\n')),

    strictRule:
      'This evidence belongs only to the current video. Ignore all previous videos, previous topics, previous captions, and previous workflow examples.',
  },
};

const raw = $json.response || '';
const ctx = $('Build Content Context').item.json || {};

const cleanText = (text = '') =>
  String(text || '').replace(/\s+/g, ' ').trim();

const cleanArray = (arr = []) =>
  Array.isArray(arr) ? arr.map(cleanText).filter(Boolean) : [];

let cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

const match = cleaned.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('No JSON object found in fact sheet response: ' + raw);
}

let sheet;
try {
  sheet = JSON.parse(match[0]);
} catch (error) {
  throw new Error('Failed to parse fact sheet JSON: ' + error.message + ' | Raw: ' + raw);
}

const currentVideoId = cleanText(ctx.currentVideoId || '');
const modelVideoId = cleanText(sheet.current_video_id || '');

if (modelVideoId && modelVideoId !== currentVideoId) {
  throw new Error(`Fact sheet videoId mismatch. Expected ${currentVideoId}, got ${modelVideoId}`);
}

const toolsOrPlatforms = Array.isArray(sheet.tools_or_platforms)
  ? sheet.tools_or_platforms
      .map(item => ({
        name: cleanText(item.name || ''),
        evidence: cleanText(item.evidence || ''),
        confidence: typeof item.confidence === 'number' ? item.confidence : null,
      }))
      .filter(item => item.name)
  : [];

const factSheet = {
  currentVideoId,
  currentVideoName: cleanText(ctx.currentVideoName || ''),

  mainTopic: cleanText(sheet.main_topic || ''),
  contentType: cleanText(sheet.content_type || ''),
  workflowGoal: cleanText(sheet.workflow_goal || ''),
  inputTrigger: cleanText(sheet.input_trigger || ''),
  mainSteps: cleanArray(sheet.main_steps || []),
  finalOutput: cleanText(sheet.final_output || ''),

  toolsOrPlatforms,
  mustMention: cleanArray(sheet.must_mention || []),
  mustNotMention: cleanArray(sheet.must_not_mention || []),
  captionAngle: cleanText(sheet.caption_angle || ''),
  confidence: typeof sheet.confidence === 'number' ? sheet.confidence : null,
  shortRationale: cleanText(sheet.short_rationale || ''),
  qualityFlags: cleanArray(sheet.quality_flags || []),

  sourceEvidence: {
    transcript: cleanText(ctx.transcript || ''),
    visualEvidenceText: cleanText(ctx.visualEvidenceText || ''),
    transcriptReliable: ctx.transcriptReliable ?? null,
  },
};

if (!factSheet.mainTopic && !factSheet.workflowGoal) {
  throw new Error('Fact sheet is too weak: missing mainTopic and workflowGoal.');
}

if (!factSheet.mainSteps.length && !factSheet.finalOutput) {
  throw new Error('Fact sheet is too weak: missing mainSteps and finalOutput.');
}

return {
  json: {
    factSheet,

    // Compatibility for old node references if needed
    resolvedBrief: {
      topic: factSheet.mainTopic,
      contentType: factSheet.contentType,
      sourceUsed: 'current video evidence',
      confidence: factSheet.confidence,
      workflowSummary: factSheet.workflowGoal,
      toolsOrPlatforms: factSheet.toolsOrPlatforms.map(t => t.name),
      keyPoints: factSheet.mainSteps,
      captionAngle: factSheet.captionAngle,
      avoidTerms: factSheet.mustNotMention,
      shortRationale: factSheet.shortRationale,
    },
  },
};

const raw = $json.response || '';
const drive = $('Google Drive Trigger').item.json || {};
const factSheet = $('Parse Current Video Fact Sheet').item.json.factSheet || {};

function normalizeTerms(value = '') {
  return String(value || '')
    .replace(/\bN\s*&\s*N\b/gi, 'n8n')
    .replace(/\bN\s+and\s+N\b/gi, 'n8n')
    .replace(/\bN\s*8\s*N\b/gi, 'n8n')
    .replace(/\bN8N\b/g, 'n8n')
    .replace(/\bn8N\b/g, 'n8n')
    .replace(/\bNADN\b/gi, 'n8n')
    .replace(/\bN\s*A\s*D\s*N\b/gi, 'n8n')
    .replace(/\bOlima\b/gi, 'Ollama')
    .replace(/\bO\s*lama\b/gi, 'Ollama')
    .replace(/\bollma\b/gi, 'Ollama');
}

function cleanText(text = '') {
  return normalizeTerms(text)
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanArray(arr = []) {
  const safeArr = Array.isArray(arr) ? arr : [];

  const output = [];

  for (const item of safeArr) {
    const cleaned = cleanText(item);

    if (cleaned) {
      output.push(cleaned);
    }
  }

  return output;
}

function uniqueValues(arr = []) {
  const safeArr = Array.isArray(arr) ? arr : [];
  const seen = new Set();
  const output = [];

  for (const item of safeArr) {
    const cleaned = cleanText(item);

    if (!cleaned) continue;

    const key = cleaned.toLowerCase();

    if (!seen.has(key)) {
      seen.add(key);
      output.push(cleaned);
    }
  }

  return output;
}

function smartTruncate(text = '', max = 100) {
  const cleaned = cleanText(text);

  if (cleaned.length <= max) {
    return cleaned;
  }

  const cut = cleaned.slice(0, max + 1);
  const lastSpace = cut.lastIndexOf(' ');
  const output = lastSpace > 35 ? cut.slice(0, lastSpace) : cleaned.slice(0, max);

  return output
    .replace(/[.,;:|/-]+$/g, '')
    .trim();
}

function sentence(text = '') {
  const cleaned = cleanText(text);

  if (!cleaned) {
    return '';
  }

  return /[.!?]$/.test(cleaned) ? cleaned : `${cleaned}.`;
}

function lowerFirst(text = '') {
  const cleaned = cleanText(text);

  if (!cleaned) {
    return '';
  }

  return cleaned.charAt(0).toLowerCase() + cleaned.slice(1);
}

function hashtagsToText(arr = [], max = 10) {
  const safeArr = cleanArray(arr);
  const output = [];

  for (const item of safeArr.slice(0, max)) {
    const cleaned = String(item)
      .replace(/^#/, '')
      .replace(/\s+/g, '')
      .trim();

    if (cleaned) {
      output.push(`#${cleaned}`);
    }
  }

  return output.join(' ');
}

function tagObjects(arr = []) {
  const safeArr = cleanArray(arr);
  const output = [];

  for (const item of safeArr) {
    const value = String(item)
      .replace(/^#/, '')
      .trim();

    if (value) {
      output.push({
        value,
        label: value,
      });
    }
  }

  return output;
}

function combineCaption(caption = '', hashtags = [], maxHashtags = 10) {
  const captionText = cleanText(caption);
  const hashtagText = hashtagsToText(hashtags, maxHashtags);

  return [captionText, hashtagText]
    .filter(Boolean)
    .join('\n\n');
}

let cleanedResponse = String(raw || '')
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const jsonMatch = cleanedResponse.match(/\{[\s\S]*\}/);

if (!jsonMatch) {
  throw new Error('No JSON object found in caption response: ' + raw);
}

let content;

try {
  content = JSON.parse(jsonMatch[0]);
} catch (error) {
  throw new Error('Failed to parse caption JSON: ' + error.message + ' | Raw: ' + raw);
}

const tools = Array.isArray(factSheet.toolsOrPlatforms)
  ? factSheet.toolsOrPlatforms
      .map((tool) => cleanText(tool.name || ''))
      .filter(Boolean)
  : [];

const mainSteps = cleanArray(factSheet.mainSteps || []);
const mustMention = cleanArray(factSheet.mustMention || []);
const mustNotMention = cleanArray(factSheet.mustNotMention || []);

const sourceText = [
  factSheet.mainTopic,
  factSheet.contentType,
  factSheet.workflowGoal,
  factSheet.inputTrigger,
  factSheet.finalOutput,
  factSheet.captionAngle,
  factSheet.shortRationale,
  ...tools,
  ...mainSteps,
  ...mustMention,
].join(' ');

const sourceLower = sourceText.toLowerCase();

const stopWords = new Set([
  'this',
  'that',
  'with',
  'from',
  'your',
  'video',
  'workflow',
  'automation',
  'automated',
  'process',
  'system',
  'content',
  'using',
  'into',
  'and',
  'the',
  'for',
  'you',
  'can',
  'how',
  'setup',
  'step',
  'steps',
  'make',
  'send',
  'receive',
  'create',
  'check',
  'post',
  'posts',
  'caption',
  'captions',
]);

const sourceWords = sourceText
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(Boolean)
  .filter((word) => word.length > 2 && !stopWords.has(word));

const importantTokens = uniqueValues(sourceWords);

function relevanceScore(text = '') {
  const lower = String(text || '').toLowerCase();

  if (!importantTokens.length) {
    return 1;
  }

  let hits = 0;
  const limit = Math.min(importantTokens.length, 10);

  for (const token of importantTokens.slice(0, limit)) {
    if (lower.includes(token)) {
      hits += 1;
    }
  }

  return hits / limit;
}

const suspiciousTerms = [
  'google drive',
  'postiz',
  'whatsapp',
  'google calendar',
  'appointment',
  'ai agent',
  'openai',
  'sports',
  'music',
  'food',
  'weather',
  'game',
  'gaming',
  'user experience',
];

function hasUnsupportedSuspiciousTerm(text = '') {
  const lower = String(text || '').toLowerCase();

  for (const term of suspiciousTerms) {
    if (lower.includes(term) && !sourceLower.includes(term)) {
      return term;
    }
  }

  for (const term of mustNotMention) {
    const cleanedTerm = cleanText(term).toLowerCase();

    if (cleanedTerm && lower.includes(cleanedTerm) && !sourceLower.includes(cleanedTerm)) {
      return term;
    }
  }

  return '';
}

function buildBaseTags() {
  const values = [
    ...tools,
    factSheet.mainTopic,
    factSheet.contentType,
    ...mainSteps.slice(0, 5),
    ...(Array.isArray(content.youtube?.tags) ? content.youtube.tags : []),
  ];

  const cleaned = [];

  for (const item of values) {
    let value = '';

    if (typeof item === 'string') {
      value = item;
    } else if (item && typeof item === 'object') {
      value = item.value || item.label || item.name || '';
    }

    value = cleanText(value).replace(/^#/, '');

    if (value) {
      cleaned.push(value);
    }
  }

  return uniqueValues(cleaned).slice(0, 10);
}

function buildYouTubeTitle() {
  const fromModel = cleanText(content.youtube?.title || '');
  const topic = cleanText(factSheet.mainTopic || '');
  const goal = cleanText(factSheet.workflowGoal || '');
  const angle = cleanText(factSheet.captionAngle || '');

  let title = fromModel;

  if (!title || title.length < 12 || title.length > 75) {
    title = topic || goal || angle || 'n8n Video Caption Automation Workflow';
  }

  if (title.length < 25 && goal) {
    title = `${title}: ${goal}`;
  }

  return smartTruncate(title, 75);
}

function buildYouTubeDescription(finalTitle, baseTags = []) {
  const topic = cleanText(factSheet.mainTopic || finalTitle || 'this workflow');
  const goal = cleanText(factSheet.workflowGoal || '');
  const trigger = cleanText(factSheet.inputTrigger || '');
  const output = cleanText(factSheet.finalOutput || '');
  const rationale = cleanText(factSheet.shortRationale || '');
  const toolPhrase = tools.length ? tools.slice(0, 6).join(', ') : 'the connected tools';

  const intro = goal
    ? sentence(`In this video, I walk through ${lowerFirst(goal)}`)
    : sentence(`In this video, I walk through ${lowerFirst(topic)}`);

  const contextLine = trigger
    ? sentence(`The workflow starts from ${lowerFirst(trigger)} and uses ${toolPhrase} to complete the process`)
    : sentence(`The workflow uses ${toolPhrase} to complete the process`);

  const outputLine = output
    ? sentence(`The final output is ${lowerFirst(output)}`)
    : sentence('The final output is a ready-to-use social media video post with a clear title, description, and caption');

  const rationaleLine = rationale
    ? sentence(rationale)
    : sentence('This setup helps make the publishing process more consistent and reduces repetitive manual caption writing');

  const stepLines = [];

  if (mainSteps.length) {
    for (const step of mainSteps.slice(0, 6)) {
      stepLines.push(`- ${sentence(step)}`);
    }
  } else {
    stepLines.push('- Prepare the video content.');
    stepLines.push('- Generate platform-ready captions.');
    stepLines.push('- Structure the output for publishing.');
  }

  const hashtags = hashtagsToText(baseTags, 10);

  return [
    finalTitle,
    '',
    intro,
    contextLine,
    outputLine,
    rationaleLine,
    '',
    'What this workflow covers:',
    stepLines.join('\n'),
    '',
    hashtags,
  ]
    .filter(Boolean)
    .join('\n')
    .trim();
}

function buildFallback(baseTags) {
  const topic = cleanText(factSheet.mainTopic || factSheet.captionAngle || 'Workflow Automation Demo');
  const goal = cleanText(factSheet.workflowGoal || '');
  const trigger = cleanText(factSheet.inputTrigger || '');
  const output = cleanText(factSheet.finalOutput || '');
  const toolNames = tools.slice(0, 5);
  const toolPhrase = toolNames.length ? toolNames.join(', ') : 'the connected tools';

  const processSentence = mainSteps.length
    ? `The workflow includes ${mainSteps.slice(0, 4).map((step) => lowerFirst(step)).join(', ')}.`
    : goal;

  const facebook = goal && output
    ? `${sentence(topic)} ${sentence(`${goal}, ending with ${output}`)}`
    : `${sentence(topic)} ${sentence(processSentence)}`;

  const instagram = goal
    ? `${topic}: ${goal}`
    : `${topic} using ${toolPhrase}.`;

  const tiktok = trigger && output
    ? `${trigger} to ${output} — automated with ${toolPhrase}.`
    : `${topic} automated with ${toolPhrase}.`;

  const youtubeTitle = buildYouTubeTitle();
  const youtubeDescription = buildYouTubeDescription(youtubeTitle, baseTags);

  return {
    facebookMessage: facebook,
    instagramCaption: combineCaption(instagram, baseTags, 7),
    tiktokCaption: combineCaption(tiktok, baseTags, 6),
    youtubeTitle,
    youtubeDescription,
    youtubeTags: tagObjects(baseTags),
    threadsCaption: combineCaption(instagram, baseTags, 2),
  };
}

const baseTags = buildBaseTags();

let facebookMessage = cleanText(content.facebook?.message || '');
let instagramCaption = combineCaption(content.instagram?.caption || '', content.instagram?.hashtags || [], 7);
let tiktokCaption = combineCaption(content.tiktok?.caption || '', content.tiktok?.hashtags || [], 6);
let youtubeTitle = buildYouTubeTitle();
let youtubeDescription = buildYouTubeDescription(youtubeTitle, baseTags);
let youtubeTags = tagObjects(baseTags);
let threadsCaption = combineCaption(
  content.threads?.caption || content.instagram?.caption || content.facebook?.message || '',
  content.threads?.hashtags || [],
  2
);

const combinedOutput = [
  facebookMessage,
  instagramCaption,
  tiktokCaption,
  youtubeTitle,
  youtubeDescription,
  threadsCaption,
].join(' ');

const unsupportedTerm = hasUnsupportedSuspiciousTerm(combinedOutput);
const score = relevanceScore(combinedOutput);

const outputLooksWrong =
  score < 0.25 ||
  Boolean(unsupportedTerm) ||
  !youtubeTitle ||
  youtubeTitle.length < 12 ||
  youtubeTitle.length > 75 ||
  !youtubeDescription ||
  youtubeDescription.length < 120;

let fallbackUsed = false;

if (outputLooksWrong) {
  const fallback = buildFallback(baseTags);

  facebookMessage = fallback.facebookMessage;
  instagramCaption = fallback.instagramCaption;
  tiktokCaption = fallback.tiktokCaption;
  youtubeTitle = fallback.youtubeTitle;
  youtubeDescription = fallback.youtubeDescription;
  youtubeTags = fallback.youtubeTags;
  threadsCaption = fallback.threadsCaption;

  fallbackUsed = true;
}

return {
  json: {
    videoName: cleanText(drive.name || factSheet.currentVideoName || ''),
    videoId: cleanText(drive.id || factSheet.currentVideoId || ''),

    contentBrief: {
      topic: cleanText(factSheet.mainTopic || ''),
      contentType: cleanText(factSheet.contentType || ''),
      sourceUsed: 'current video fact sheet',
      confidence: factSheet.confidence ?? null,
      workflowSummary: cleanText(factSheet.workflowGoal || ''),
      inputTrigger: cleanText(factSheet.inputTrigger || ''),
      finalOutput: cleanText(factSheet.finalOutput || ''),
      toolsOrPlatforms: tools,
      keyPoints: mainSteps,
      captionAngle: cleanText(factSheet.captionAngle || ''),
      avoidTerms: mustNotMention,
      shortRationale: cleanText(factSheet.shortRationale || ''),
    },

    qualityCheck: {
      relevanceScore: score,
      fallbackUsed,
      unsupportedTerm,
      importantTokens: importantTokens.slice(0, 25),
      currentVideoId: cleanText(factSheet.currentVideoId || ''),
      youtubeDescriptionLength: youtubeDescription.length,
    },

    facebookMessage,
    instagramCaption,
    tiktokCaption,
    youtubeTitle: smartTruncate(youtubeTitle, 75),
    youtubeDescription,
    youtubeTags,
    threadsCaption,
  },
};

const drive = $('Google Drive Trigger').item.json || {};
const captions = $('Validate Captions and Finalize').item.json || {};
const payloadData = $('Build Postiz Payload').item.json || {};
const uploadData = $('Postiz Upload').item.json || {};
const postizResponse = $json || {};

const clean = (value = '') =>
  String(value || '').replace(/\s+/g, ' ').trim();

const truncate = (value = '', max = 3000) => {
  const text = clean(value);
  return text.length > max ? text.slice(0, max - 3).trim() + '...' : text;
};

const executionId =
  typeof $execution !== 'undefined' && $execution.id
    ? String($execution.id)
    : String(Date.now());

const timestamp = new Date().toISOString();

const posts = Array.isArray(payloadData.postizPayload?.posts)
  ? payloadData.postizPayload.posts
  : [];

const skippedPlatforms = Array.isArray(payloadData.skippedPlatforms)
  ? payloadData.skippedPlatforms
  : [];

const body = postizResponse.body || postizResponse;

const statusCode = Number(
  postizResponse.statusCode ||
  postizResponse.status ||
  postizResponse.body?.statusCode ||
  body.statusCode ||
  0
);

const errorMessage = clean(
  postizResponse.error?.message ||
  postizResponse.error ||
  postizResponse.body?.error?.message ||
  postizResponse.body?.message ||
  postizResponse.message ||
  body.error?.message ||
  body.error ||
  body.message ||
  ''
);

const postizPostId = clean(
  body.id ||
  body.postId ||
  body.data?.id ||
  body.data?.postId ||
  body.launch?.id ||
  body.result?.id ||
  body.post?.id ||
  body.posts?.[0]?.id ||
  ''
);

const postizUploadId = clean(
  uploadData.id ||
  uploadData.uploadId ||
  uploadData.data?.id ||
  uploadData.result?.id ||
  payloadData.uploadId ||
  ''
);

const videoName = clean(
  captions.videoName ||
  payloadData.videoName ||
  drive.name ||
  ''
);

const videoId = clean(
  captions.videoId ||
  payloadData.videoId ||
  drive.id ||
  ''
);

const responseHasError =
  Boolean(postizResponse.error) ||
  Boolean(body.error) ||
  statusCode >= 400 ||
  String(postizResponse.name || '').toLowerCase().includes('error') ||
  String(body.name || '').toLowerCase().includes('error');

const responseLooksEmpty =
  !postizPostId &&
  !body.id &&
  !body.data &&
  !body.result &&
  !body.launch &&
  !Array.isArray(body.posts) &&
  !body.success &&
  !body.status &&
  !statusCode &&
  !errorMessage;

const hasTargetPosts = posts.length > 0;

const success =
  hasTargetPosts &&
  !responseHasError &&
  !responseLooksEmpty;

function formatPlatform(value = '') {
  const p = clean(value).toLowerCase();

  if (p.includes('tiktok')) return 'TikTok';
  if (p.includes('instagram')) return 'Instagram';
  if (p.includes('youtube')) return 'YouTube';
  if (p.includes('facebook')) return 'Facebook';
  if (p.includes('threads')) return 'Threads';
  if (p === 'x' || p.includes('twitter')) return 'X';
  if (p.includes('pinterest')) return 'Pinterest';

  return clean(value || 'Unknown');
}

function titleFromCaption(text = '') {
  const cleaned = clean(text);

  if (!cleaned) return '';

  const firstLine = cleaned
    .split('\n')
    .map((line) => clean(line))
    .find(Boolean) || '';

  if (!firstLine) return '';

  return truncate(firstLine.replace(/^#+\s*/g, ''), 120);
}

function getFallbackTitle(platform = '', post = {}) {
  const p = platform.toLowerCase();

  const postContent = clean(post.value?.[0]?.content || '');

  const title =
    captions.youtubeTitle ||
    captions.contentBrief?.topic ||
    payloadData.contentBrief?.topic ||
    captions.contentBrief?.workflowSummary ||
    payloadData.contentBrief?.workflowSummary ||
    titleFromCaption(postContent) ||
    titleFromCaption(captions.instagramCaption) ||
    titleFromCaption(captions.facebookMessage) ||
    titleFromCaption(captions.youtubeDescription) ||
    titleFromCaption(captions.threadsCaption) ||
    '';

  if (!title) return '';

  if (p.includes('facebook')) return title;
  if (p.includes('instagram')) return title;
  if (p.includes('threads')) return title;
  if (p.includes('youtube')) return title;
  if (p.includes('tiktok')) return title;
  if (p.includes('pinterest')) return title;

  return title;
}

function getPostType(platform = '', post = {}) {
  const p = platform.toLowerCase();
  const settings = post.settings || {};
  const postType = clean(settings.post_type || settings.type || '').toLowerCase();

  if (p.includes('tiktok')) return 'Short Video';

  if (p.includes('instagram')) {
    if (postType === 'story') return 'Story';
    if (postType === 'reel') return 'Reel';
    if (postType === 'post') return 'Post';
    return 'Post';
  }

  if (p.includes('youtube')) {
    return 'Video / Short';
  }

  if (p.includes('facebook')) {
    return 'Video / Post';
  }

  if (p.includes('threads')) {
    return 'Post';
  }

  if (p === 'x' || p.includes('twitter')) {
    return 'Post';
  }

  if (p.includes('pinterest')) {
    return 'Pin';
  }

  return 'Post';
}

function getTitle(platform = '', post = {}) {
  const p = platform.toLowerCase();

  const fallbackTitle = getFallbackTitle(platform, post);

  if (p.includes('youtube')) {
    return clean(captions.youtubeTitle || post.settings?.title || fallbackTitle);
  }

  if (p.includes('tiktok')) {
    return clean(post.settings?.title || captions.youtubeTitle || fallbackTitle);
  }

  if (p.includes('pinterest')) {
    return clean(post.settings?.title || captions.youtubeTitle || fallbackTitle);
  }

  if (p.includes('facebook')) {
    return fallbackTitle;
  }

  if (p.includes('instagram')) {
    return fallbackTitle;
  }

  if (p.includes('threads')) {
    return fallbackTitle;
  }

  return clean(post.settings?.title || fallbackTitle);
}

function getCaption(platform = '', post = {}) {
  const p = platform.toLowerCase();
  const postContent = clean(post.value?.[0]?.content || '');

  if (p.includes('tiktok')) {
    return clean(captions.tiktokCaption || postContent);
  }

  if (p.includes('instagram')) {
    return clean(captions.instagramCaption || postContent);
  }

  if (p.includes('facebook')) {
    return clean(captions.facebookMessage || postContent);
  }

  if (p.includes('youtube')) {
    return clean(captions.youtubeDescription || postContent);
  }

  if (p.includes('threads')) {
    return clean(captions.threadsCaption || postContent);
  }

  if (p.includes('pinterest')) {
    return clean(captions.pinterestDescription || postContent);
  }

  return postContent;
}

const failureReason = responseLooksEmpty
  ? 'Create Post in Postiz returned an empty or incomplete response'
  : errorMessage || 'Postiz post creation failed';

let logRows = posts.map((post) => {
  const rawPlatform = clean(post.settings?.__type || 'Unknown');
  const platform = formatPlatform(rawPlatform);

  return {
    execution_id: executionId,
    timestamp,
    status: success ? 'SUCCESS' : 'FAILED',
    video_name: videoName,
    video_id: videoId,
    platform,
    post_type: getPostType(platform, post),
    title: truncate(getTitle(platform, post), 300),
    caption: truncate(getCaption(platform, post), 3000),
    postiz_upload_id: postizUploadId,
    postiz_post_id: postizPostId,
    error_message: success ? '' : truncate(failureReason, 3000),
    failed_node: success ? '' : 'Create Post in Postiz',
  };
});

if (!logRows.length) {
  const fallbackTitle = clean(
    captions.youtubeTitle ||
    captions.contentBrief?.topic ||
    payloadData.contentBrief?.topic ||
    ''
  );

  logRows = [
    {
      execution_id: executionId,
      timestamp,
      status: 'FAILED',
      video_name: videoName,
      video_id: videoId,
      platform: 'Unknown',
      post_type: 'Post',
      title: truncate(fallbackTitle, 300),
      caption: truncate(
        captions.youtubeDescription ||
          captions.tiktokCaption ||
          captions.instagramCaption ||
          captions.facebookMessage ||
          captions.threadsCaption ||
          '',
        3000
      ),
      postiz_upload_id: postizUploadId,
      postiz_post_id: postizPostId,
      error_message: 'No target platform posts were found in Build Postiz Payload',
      failed_node: 'Build Postiz Payload',
    },
  ];
}

const platformList = logRows.map((row) => row.platform).join(', ');

const skippedPlatformList = skippedPlatforms.length
  ? skippedPlatforms.join(', ')
  : 'None';

const telegramMessage = success
  ? `✅ Video automation completed

Video: ${videoName}
Status: SUCCESS
Posted Platforms: ${platformList}
Skipped Platforms: ${skippedPlatformList}
Postiz Post ID: ${postizPostId || 'N/A'}
Time: ${timestamp}
Execution ID: ${executionId}`
  : `❌ Video automation failed at posting stage

Video: ${videoName}
Status: FAILED
Target Platforms: ${platformList}
Skipped Platforms: ${skippedPlatformList}
Failed Node: ${logRows[0]?.failed_node || 'Create Post in Postiz'}
Error: ${truncate(logRows[0]?.error_message || failureReason, 3000)}
Time: ${timestamp}
Execution ID: ${executionId}`;

return {
  json: {
    execution_id: executionId,
    timestamp,
    status: success ? 'SUCCESS' : 'FAILED',
    video_name: videoName,
    video_id: videoId,
    platforms: platformList,
    skipped_platforms: skippedPlatformList,
    postiz_post_id: postizPostId,
    postiz_upload_id: postizUploadId,
    logRows,
    telegramMessage,
  },
};

const rows = $json.logRows || [];

return rows.map(row => ({
  json: row,
}));

const ALLOW_POSTING = true;
// true = live posting mode
// false = caption testing only

return {
  json: {
    ...$json,
    allowPosting: ALLOW_POSTING,
    postingMode: ALLOW_POSTING ? 'LIVE_POSTING' : 'CAPTION_ONLY',
    checkedAt: new Date().toISOString(),
  },
};

const inputItem = $input.first();
const data = inputItem?.json || {};

const rows = Array.isArray(data.logRows) ? data.logRows : [];
const skippedPlatforms = data.skipped_platforms || data.skippedPlatforms || 'None';

function clean(value = '') {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function limit(value = '', max = 900) {
  const text = clean(value);
  return text.length > max ? text.slice(0, max - 3) + '...' : text;
}

function titleLine(title = '') {
  const cleaned = clean(title);

  if (!cleaned || cleaned === 'N/A') {
    return '';
  }

  return `Title: ${cleaned}\n`;
}

if (!rows.length) {
  return [
    {
      json: {
        telegramMessage: `❌ Video automation log failed

No platform log rows were found.
Video: ${clean(data.video_name || 'N/A')}
Status: FAILED
Time: ${clean(data.timestamp || new Date().toISOString())}
Execution ID: ${clean(data.execution_id || 'N/A')}`,
      },
    },
  ];
}

return rows.map((row) => {
  const status = clean(row.status || data.status || 'UNKNOWN');
  const success = status === 'SUCCESS';
  const icon = success ? '✅' : '❌';

  const platform = clean(row.platform || 'Unknown');
  const videoName = clean(row.video_name || data.video_name || 'N/A');
  const postType = clean(row.post_type || 'N/A');
  const title = clean(row.title || '');
  const uploadId = clean(row.postiz_upload_id || data.postiz_upload_id || 'N/A');
  const postId = clean(row.postiz_post_id || data.postiz_post_id || 'N/A');
  const timestamp = clean(row.timestamp || data.timestamp || new Date().toISOString());
  const executionId = clean(row.execution_id || data.execution_id || 'N/A');
  const errorMessage = limit(row.error_message || 'Postiz post creation failed', 900);
  const failedNode = clean(row.failed_node || 'Create Post in Postiz');

  const telegramMessage = success
    ? `✅ ${platform} post created

Video: ${videoName}
Status: SUCCESS
Platform: ${platform}
Post Type: ${postType}
${titleLine(title)}Postiz Upload ID: ${uploadId}
Postiz Post ID: ${postId}
Skipped Platforms: ${skippedPlatforms}
Time: ${timestamp}
Execution ID: ${executionId}`
    : `❌ ${platform} post failed

Video: ${videoName}
Status: FAILED
Platform: ${platform}
Post Type: ${postType}
${titleLine(title)}Failed Node: ${failedNode}
Error: ${errorMessage}
Skipped Platforms: ${skippedPlatforms}
Time: ${timestamp}
Execution ID: ${executionId}`;

  return {
    json: {
      ...row,
      telegramMessage,
    },
  };
});
